  candidate_commit: string;
  verification_id: string;
  check: string;
  count: number;
  stopped: boolean;
  failure: unknown;
}

export interface A2AReview {
  review_id: string;
  task_id: string;
  attempt: A2AAttempt;
  candidate_commit: string;
  spec_rev: number;
  card_snapshot_id: string;
  verification_id: string;
  thread_id: string;
  session_id: string;
  workspace: string;
  requested_at: string;
  launch_id: string | null;
  runtime_identity: A2ARuntimeIdentity | null;
  state: "requested" | "running" | "passed" | "needs_fix" | "unknown" | "cancelled";
  result?: { verdict: "可合并" | "需修复"; findings: A2AReviewFinding[]; turn_id: string; received_at: string };
}

export interface A2AReviewFinding {
  location: { path: string; line: number };
  failure_scenario: string;
  suggestion: string;
}

export interface A2ACommandResult {
  argv: string[];
  cwd: string;
  stdout: string | null;
  stderr: string | null;
  exit: number | null;
  returncode: number | null;
  outcome?: string;
}

export interface A2AVerification {
  verification_id: string;
  attempt: A2AAttempt;
  spec_rev: number;
  G: string;
  C: string;
  M: string | null;
  card_snapshot_id: string;
  card_version: number;
  commands: { argv: string[]; cwd: string }[];
  results: A2ACommandResult[];
  workspace: string;
  state: "running" | "passed" | "failed" | "interrupted" | "unknown" | "merge_failed";
  command_intent?: { argv: string[]; cwd: string };
  result?: A2ACommandResult;
  ended?: string;
  quality?: {
    snapshot: ProjectQuality;
    red: { index: number; B: string; C: string; test_paths: string[]; base_workspace: string; candidate_workspace: string;
      base_result: A2ACommandResult; candidate_result: A2ACommandResult; passed: boolean }[];
    rules: { id: string; result: A2ACommandResult; passed: boolean }[];
  };
}

export interface A2ATask {
  task_id: string;
  title?: string;
  project_id: string;
  repo: string;
  integration_ref: string;
  card_snapshot_id: string;
  card_version: number;
  card: TaskCard;
  base_commit: string;
  state: string;
  spec_rev: number;
  fence: number;
  current_attempt: A2AAttempt | null;
  candidate_commit: string | null;
  verification: A2AVerification | null;
  repair?: A2ARepair | null;
  review?: A2AReview | null;
  quality?: ProjectQuality;
  integration_intent: {
    G: string;
    M: string;
    verification_id: string;
    attempt: A2AAttempt;
    spec_rev?: number;
    C?: string;
    card_snapshot_id: string;
    integration_ref: string;
    worktree: string | null;
    intent_id?: string;
    command_intent?: { argv: string[]; cwd: string };
    result?: A2ACommandResult;
    state: "pending" | "completed";
    score?: { score_id: string; data: Record<string, unknown> };
  } | null;
}

/** A normal native session with a display role, never a delivery attempt. */
export interface A2AAttachment {
  task_id: string;
  thread_id: string;
  role: typeof A2AMemberRole.Type;
  modelSelection: typeof ModelSelection.Type;
  runtime_mode: "approval-required" | "full-access" | "workspace-write";
  state: "creating" | "active" | "ended";
  ended_at?: string;
  preset?: A2ASessionPreset;
}

export interface A2ARun {
  run_id: string;
- **批准与派发分开**（2026-10-10 用户决定，依据 T-074 实测：Codex 等批准时注入的文字被当作同意）：受管 worker 以"不问"的审批模式启动（Codex `approval_policy=never`、Claude `--permission-mode dontAsk`），越界操作被拒并由 worker 上报，窗格里没有批准窗口；主控窗格保留批准，只在空闲时注入，其余时间排队。空闲由编排后台自己判断：所有输入经后台写进 node-pty，后台写入提交用的回车（含用户敲的）时就记"忙"，收到"回合结束"事件才回到"空闲"；Esc 中断等收不到回合结束的情况，排队消息由用户放行（2026-10-11 用户决定；权限请求 hook 没有结束事件与请求标识，回合开始事件有延迟，见 T-074）。注入方法用 bracketed paste 后单独回车。

## 7. 面板

- 同一个面板收两类条目：worker、reviewer、monitor 的**问题上报**（语义同 controller-split spec 第 4 节，处置规则不变）；构思主控的**主控提问**。
- 主控提问由构思主控用命令放上面板，每题带类型、选项、推荐和依据。
- 用户逐题点选、采纳推荐或写几句，草稿自动保存；可逐个或打包发送，已答两题以上默认打包，格式"问题 N：…… / 用户答复：……"；答复写进提问方的窗格，每条记为 `answer` 用户输入并指向问题。
- 执行主控的 needs-decision 由构思主控改写后放上面板；用户在对话里答的，面板标"已在对话中答复"。
- 系统通知：新的"等你决定"、blocking、完成报告、BLOCKED/NO_GO 时发；通知读取失败不能悄悄停掉（原 T-057、T-067 的要求）。

## 8. 追溯、打分、复盘与指标

**提交尾注**：`A2A-Task`、`A2A-Attempt`、`A2A-Session`、`A2A-Role`、`A2A-Tool`（CLI 与版本）、`A2A-Model`、`A2A-Effort`、`A2A-Native-Session`、`A2A-Launch`。提交时的模型取该会话最近一轮的记录，拿不到写 `unknown`。门禁核对规则见 T-072；没有尾注的提交记为用户本人提交与人工介入，标"推断：缺尾注"。

**验收打分**：每个 attempt 结束时一条，是集成或放弃命令的参数。

| 字段 | 谁填 |
| --- | --- |
| 时间、任务卡、项目、CLI、模型、强度、任务类型、复杂度、交付轮数、耗时、人工介入次数、各项检查的打回次数 | 脚本 |
| 结果：通过、升级（换更强的执行器重做）、放弃（只记理由，不打分） | 执行主控 |
| 边界纪律 0–3（3 严守边界，0 大面积自作主张）加理由 | 执行主控 |
| 工程品味 0–3（3 拿来即用，0 看着就想重写）加理由 | 执行主控 |
| 备注 | 执行主控 |
| 用户自己的分 | 用户，另存一条，不覆盖 |
"}}

