export class TaskCardError extends Error {
  readonly field: string;
  constructor(field: string, message: string) {
    super(message);
    this.field = field;
  }
}
function check(value: unknown, field: string, message: string): asserts value {
  if (!value) throw new TaskCardError(field, message);
}
function object(value: any, fields: string[], field: string) {
  check(value && typeof value === "object" && !Array.isArray(value), field, "Object required.");
  check(Object.keys(value).length === fields.length && fields.every((key) => Object.hasOwn(value, key)),
    field, "Fields do not match the task card schema.");
}
function nonempty(value: unknown, field: string): asserts value is string {
  check(typeof value === "string" && value.trim() && !value.includes("\0"), field, "Nonempty text required.");
}
function strings(value: unknown, field: string, minimum = 0): asserts value is string[] {
  check(Array.isArray(value) && value.length >= minimum, field, "Array has too few entries.");
  value.forEach((item, i) => nonempty(item, `${field}[${i}]`));
}

export function commandArgv(value: unknown, field: string): string[] {
  check(Array.isArray(value) && value.length > 0 &&
    value.every((arg) => typeof arg === "string" && !arg.includes("\0")), field, "Command argv required.");
  const argv = [...value] as string[];
  nonempty(argv[0], field);
  check(argv.every((arg) => !arg.includes("{worktree}") || arg === "{worktree}"), field,
    "The worktree token must occupy one complete argument.");
  const executable = argv[0];
  const paths = isAbsolute(executable) ? [executable] : executable.includes("/") ? [] :
    (process.env.PATH ?? "").split(":").filter(isAbsolute).map((dir) => join(dir, executable));
  let resolved: string | undefined;
  for (const path of paths) {
    try {
      accessSync(path, constants.X_OK);
      if (statSync(path).isFile()) { resolved = realpathSync(path); break; }
    } catch (error) {
      if (!["ENOENT", "EACCES", "ENOTDIR"].includes((error as NodeJS.ErrnoException).code ?? "")) throw error;
    }
  }
  check(resolved, field, "Executable is unavailable.");
  argv[0] = resolved;
  return argv;
}

export interface ProjectQuality {
  source_commit: string;
  path: ".a2a/quality.json";
  raw: string | null;
  rule_checks: { id: string; argv: string[] }[];
}

export function projectRules(value: unknown): ProjectQuality["rule_checks"] {
  object(value, ["schema", "rule_checks"], "project_quality");
  const config = value as { schema: unknown; rule_checks: unknown[] };
  check(config.schema === 1 && Array.isArray(config.rule_checks), "project_quality", "Schema 1 and rule_checks array required.");
  const ids = new Set<string>();
  return config.rule_checks.map((input: any, index) => {
    const field = `project_quality.rule_checks[${index}]`;
    object(input, ["id", "argv"], field);
    nonempty(input.id, field + ".id");
    check(!ids.has(input.id), field, "Rule IDs must be unique."); ids.add(input.id);
    return { id: input.id, argv: commandArgv(input.argv, field + ".argv") };
  });
}

export function ticketSource(path: string) {
  check(isAbsolute(path), "source.ticket", "Absolute ticket path required.");
  const content = readFileSync(path, "utf8");
  const lines = content.split(/\r?\n/);
  check(lines[0] === "---", "source.ticket", "Ticket frontmatter required.");
  const end = lines.indexOf("---", 1);
  check(end > 0, "source.ticket", "Ticket frontmatter is incomplete.");
  const fields = new Map<string, string>();
  for (const line of lines.slice(1, end)) {
    const separator = line.indexOf(":");
    if (separator < 1) continue;
    const key = line.slice(0, separator);
    check(!fields.has(key), "source.ticket", "Duplicate ticket field.");
    fields.set(key, line.slice(separator + 1).trim());
  }
  const ticketId = fields.get("id"), rev = Number(fields.get("ready_rev"));
  check(ticketId && fields.get("ready") === "yes" && Number.isSafeInteger(rev) && rev > 0,
    "source", "A ready ticket and a positive ready_rev are required.");
  return { ticketId, source: { ticket: realpathSync(path), ready_rev: rev } };
}

export function taskCardTemplate(id: string, ticket?: string): TaskCard {
  const source = ticket ? ticketSource(ticket) : null;
  if (source) check(id.startsWith(source.ticketId + "-") && /^[1-9][0-9]*$/.test(id.slice(source.ticketId.length + 1)),
    "id", "Card ID must contain the ticket ID and a sequence number.");
  return { id, source: source?.source ?? null, goal: "", non_goals: [], paths: { allow: [], deny: [] },
    completion_conditions: [], red_commands: [], task_type: "后端逻辑", repair_target: null,
    complexity: "M", executor: { cli: "Codex", model: "", effort: "" }, base_commit: null, writer: null };
}

export function validateTaskCard(input: unknown, id: string): TaskCard {
  const card = structuredClone(input) as TaskCard;
  object(card, ["id", "source", "goal", "non_goals", "paths", "completion_conditions", "red_commands",
    "task_type", "repair_target", "complexity", "executor", "base_commit", "writer"], "card");
  check(card.id === id, "id", "Card ID does not match the task.");
  if (card.source !== null) {
    object(card.source, ["ticket", "ready_rev"], "source");
    nonempty(card.source.ticket, "source.ticket");
    const source = ticketSource(card.source.ticket);
    check(card.source.ready_rev === source.source.ready_rev, "source.ready_rev", "Ticket revision does not match.");
    check(id.startsWith(source.ticketId + "-") && /^[1-9][0-9]*$/.test(id.slice(source.ticketId.length + 1)),
      "id", "Card ID must contain the ticket ID and a sequence number.");
    card.source = source.source;
  }
  nonempty(card.goal, "goal");
  strings(card.non_goals, "non_goals", 1);
  object(card.paths, ["allow", "deny"], "paths");
  for (const kind of ["allow", "deny"] as const) {
    strings(card.paths[kind], "paths." + kind, kind === "allow" ? 1 : 0);
    for (const path of card.paths[kind]) {
      const parts = path.replace(/\/$/, "").split("/");
      check(path === "." || (!isAbsolute(path) && !path.includes("\\") && !/[\x00-\x1f*?\[\]:]/.test(path) &&
        parts.every((part) => part && part !== "." && part !== "..")), "paths." + kind, "Invalid repository path.");
    }
  }
  for (const key of ["completion_conditions", "red_commands"] as const) {
    check(Array.isArray(card[key]) && (key === "red_commands" || card[key].length > 0), key, "Command array required.");
    for (const [i, command] of card[key].entries()) {
      const field = `${key}[${i}]`;
      object(command, key === "red_commands" ? ["argv", "test_paths"] : ["argv"], field);
      command.argv = commandArgv(command.argv, field);
      if (key === "red_commands") {
        const paths = (command as TaskCard["red_commands"][number]).test_paths;
        strings(paths, field + ".test_paths", 1);
        check(new Set(paths).size === paths.length, field, "Test paths must be unique.");
        for (const path of paths) {
          const parts = path.split("/");
          check(!isAbsolute(path) && !path.includes("\\") && !/[\x00-\x1f*?\[\]:]/.test(path) &&
            parts.every((part) => part && part !== "." && part !== ".." && part.toLowerCase() !== ".git"),
            field + ".test_paths", "Exact repository file paths are required.");
        }
      }
    }
  }
  check(["后端逻辑", "前端界面", "缺陷修复", "测试", "重构", "构建与基础设施", "文档", "调研"].includes(card.task_type),
    "task_type", "Unknown task type.");
  if (card.task_type === "缺陷修复") nonempty(card.repair_target, "repair_target");
  else check(card.repair_target === null || typeof card.repair_target === "string", "repair_target", "Text or null required.");
  check(["S", "M", "L"].includes(card.complexity), "complexity", "Complexity must be S, M or L.");
  object(card.executor, ["cli", "model", "effort"], "executor");
  check(["Claude Code", "Codex"].includes(card.executor.cli), "executor.cli", "CLI must be Claude Code or Codex.");
  nonempty(card.executor.model, "executor.model");
  nonempty(card.executor.effort, "executor.effort");
  check(card.base_commit === null && card.writer === null, "writer", "The gate fills the base commit and writer during claim.");
  return card;
}

export function pathAllowed(card: TaskCard, path: string): boolean {
  const matches = (rule: string) => rule === "." || (rule.endsWith("/") ? path.startsWith(rule) : path === rule);
  return card.paths.allow.some(matches) && !card.paths.deny.some(matches);
}
import { Refusal } from "./gates/core.ts";
import type { RelayFile } from "./relayFiles.ts";
import { OrchestrationStore } from "./store.ts";
import { reviewRequest } from "./gates/qualityProtocol.ts";

export interface RelayBinding {
  id: string; task: string; attempt: string; session: string; fence: number; spec_rev: number;
  role: "worker" | "reviewer";
  review_id?: string;
}
const keyPattern = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;

// Intent is durable before gate execution. A missing outcome is unknown, never
// authorization to repeat an operation after an interrupted transfer.
export class RequestRelay {
  readonly store: OrchestrationStore;
  constructor(store: OrchestrationStore) {
    this.store = store;
    store.db.exec(`CREATE TABLE IF NOT EXISTS relay_requests (
      key TEXT PRIMARY KEY, launch TEXT NOT NULL, task TEXT NOT NULL, attempt TEXT NOT NULL,
      request_id TEXT, input TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS relay_results (key TEXT PRIMARY KEY, data TEXT NOT NULL, created_at TEXT NOT NULL);`);
    for (const table of ["relay_requests", "relay_results"]) {
      for (const operation of ["UPDATE", "DELETE"]) store.db.exec(
        `CREATE TRIGGER IF NOT EXISTS ${table}_no_${operation.toLowerCase()} BEFORE ${operation} ON ${table} BEGIN SELECT RAISE(ABORT,'append only'); END;`);
    }
  }
  async receive(binding: RelayBinding, file: RelayFile, matchedStop: boolean,
    perform: (input: Record<string, any>) => Promise<any>) {
    let input: any = null;
    let parseError: string | null = file.error ?? null;
    if (!parseError) {
      try { input = JSON.parse(file.raw!); }
      catch (error) { parseError = String(error); }
    }
    const requestId = input && typeof input.request_id === "string" && keyPattern.test(input.request_id) ? input.request_id : null;
    const key = requestId ? "id:" + requestId : `file:${binding.id}:${file.name}`;
    const canonical = input && typeof input === "object" && !Array.isArray(input)
      ? JSON.stringify(Object.fromEntries(Object.entries(input).sort(([a], [b]) => a.localeCompare(b))))
      : JSON.stringify({ raw: file.raw ?? null, error: file.error ?? null });
    const previous = this.store.db.prepare("SELECT * FROM relay_requests WHERE key=?").get(key);
    if (previous) {
      if (previous.launch !== binding.id || previous.input !== canonical) {
        const result = { ok: false, error: "relay_request_id_reused" };
        const seen = this.store.db.prepare("SELECT 1 FROM orchestration_events WHERE launch=? AND type='relay_rejected' AND json_extract(data,'$.key')=? AND json_extract(data,'$.canonical')=? LIMIT 1")
          .get(binding.id, key, canonical);
        this.store.event("relay_rejected", { key, file, canonical, result }, binding);
        return { key, request_id: requestId, replayed: Boolean(seen), result };
      }
      const row = this.store.db.prepare("SELECT data FROM relay_results WHERE key=?").get(key);
      const result = row ? JSON.parse(String(row.data)) : { ok: false, error: "relay_outcome_unknown" };
      this.store.event("relay_replayed", { key, file: file.name, result }, binding);
      return { key, request_id: requestId, replayed: true, result };
    }
    if (!matchedStop) {
      const result = { ok: false, error: "relay_requires_current_stop" };
      this.store.event("relay_rejected", { key, request_id: requestId, file, result }, binding);
      return { key, request_id: requestId, replayed: false, result };
    }
    this.store.db.prepare("INSERT INTO relay_requests(key,launch,task,attempt,request_id,input,created_at) VALUES (?,?,?,?,?,?,?)")
      .run(key, binding.id, binding.task, binding.attempt, requestId, canonical, new Date().toISOString());
    this.store.event("relay_received", { key, file, input }, binding);
    let result: any;
    try {
      if (parseError || !input || typeof input !== "object" || Array.isArray(input)) throw new Refusal("invalid_relay_request", parseError);
      if (binding.role !== "worker" && binding.role !== "reviewer") throw new Refusal("relay_role_required");
      const base = ["schema", "request_id", "command", "task", "attempt", "session", "fence", "spec_rev"];
      const allowed: Record<string, string[]> = binding.role === "reviewer"
        ? { review_submit: ["review_id", "candidate_commit", "verdict", "findings"] }
        : { submit: ["commit"], status: [], issue: ["title", "body", "blocking", "refs"] };
      const extra = allowed[input.command];
      if (input.schema !== 1 || !requestId || !extra || base.some((field) => !Object.hasOwn(input, field)) ||
          Object.keys(input).some((field) => ![...base, ...extra].includes(field)) ||
          ![input.task, input.attempt, input.session].every((value) => typeof value === "string" && keyPattern.test(value)) ||
          !Number.isSafeInteger(input.fence) || !Number.isSafeInteger(input.spec_rev)) throw new Refusal("invalid_relay_request");
      for (const field of ["task", "attempt", "session", "fence", "spec_rev"] as const) {
        if (input[field] !== binding[field]) throw new Refusal("relay_identity_mismatch", { field });
      }
      if (input.command === "review_submit") {
        reviewRequest(file.raw);
        if (input.review_id !== binding.review_id) throw new Refusal("relay_review_mismatch");
      }
      if (input.command === "submit" && (typeof input.commit !== "string" || !/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/.test(input.commit))) {
        throw new Refusal("invalid_relay_request", { field: "commit" });
      }
      if (input.command === "issue" && (typeof input.title !== "string" || !input.title.trim() || typeof input.body !== "string" ||
        (input.blocking !== undefined && typeof input.blocking !== "boolean") ||
        (input.refs !== undefined && (!Array.isArray(input.refs) || !input.refs.every((value: unknown) => typeof value === "string"))))) {
        throw new Refusal("invalid_relay_request", { field: "issue" });
      }
      const { schema: _schema, request_id: _id, ...command } = input;
      result = await perform(command);
    } catch (error) {
      result = { ok: false, error: error instanceof Refusal ? error.code : "relay_outcome_unknown",
        details: error instanceof Refusal ? error.details : String(error) };
    }
    this.store.db.prepare("INSERT INTO relay_results(key,data,created_at) VALUES (?,?,?)")
      .run(key, JSON.stringify(result), new Date().toISOString());
    this.store.event(result.ok ? "relay_processed" : "relay_rejected", { key, request_id: requestId, result }, binding);
    return { key, request_id: requestId, replayed: false, result };
  }
}
import { closeSync, constants, fstatSync, fsyncSync, openSync, readFileSync, readdirSync, realpathSync, writeFileSync } from "node:fs";
import { isAbsolute, join } from "node:path";
import { randomUUID } from "node:crypto";

export interface RelayFile { name: string; raw?: string; error?: string }

// Called only after the daemon matches an authenticated reviewer's Stop.
// The model remains read-only; the hook request handler persists its explicit JSON.
export function writeReviewRequest(directory: string, input: Record<string, any>): RelayFile {
  const root = realpathSync(directory);
  if (root !== directory || !/^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(input.request_id)) throw new Error("invalid_review_request_path");
  const name = input.request_id + ".json", raw = JSON.stringify(input) + "\n";
  let fd: number;
  try { fd = openSync(join(root, name), "wx", 0o600); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    // A repeated explicit request may reuse its file, never replace it. The
    // existing relay journal decides whether its operation already completed.
    const prior = readWorkerRequests(root).find((file) => file.name === name);
    if (!prior || prior.error || prior.raw !== raw) throw new Error("review_request_file_changed");
    return prior;
  }
  try { writeFileSync(fd, raw); fsyncSync(fd); }
  finally { closeSync(fd); }
  return { name, raw };
}

export function queueWorkerRequest(input: Record<string, any>, env = process.env) {
  const directory = env.A2A_REQUEST_DIR;
  if (!directory || !isAbsolute(directory) || env.A2A_ROLE !== "worker") throw new Error("worker_request_directory_required");
  const root = realpathSync(directory);
  const request_id = input.request_id ?? randomUUID();
  if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(request_id)) throw new Error("invalid_request_id");
  const request = { schema: 1, request_id, task: env.A2A_TASK, attempt: env.A2A_ATTEMPT,
    session: env.A2A_SESSION, fence: Number(env.A2A_FENCE), spec_rev: Number(env.A2A_SPEC_REV), ...input };
  if (!request.task || !request.attempt || !request.session || !Number.isSafeInteger(request.fence) || !Number.isSafeInteger(request.spec_rev)) {
    throw new Error("worker_binding_required");
  }
  const file = join(root, request_id + ".json");
  const fd = openSync(file, "wx", 0o600);
  try { writeFileSync(fd, JSON.stringify(request) + "\n"); fsyncSync(fd); }
  finally { closeSync(fd); }
  return { ok: true, queued: true, delivered: false, request_id, path: file };
}

export function readWorkerRequests(directory: string): RelayFile[] {
  if (!isAbsolute(directory)) throw new Error("worker_request_directory_required");
  if (realpathSync(directory) !== directory) throw new Error("request_directory_changed");
  return readdirSync(directory).filter((name) => name.endsWith(".json")).sort().map((name) => {
    const file = join(directory, name);
    try {
      const fd = openSync(file, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
      try {
        if (!fstatSync(fd).isFile()) return { name, error: "request_must_be_regular_file" };
        return { name, raw: readFileSync(fd, "utf8") };
      }
      finally { closeSync(fd); }
    } catch (error) { return { name, error: String(error) }; }
  });
}
import { createServer } from "node:net";
import { chmodSync, existsSync, mkdirSync, readFileSync, realpathSync, statSync, unlinkSync, writeFileSync } from "node:fs";
import { isAbsolute, join } from "node:path";
import { A2AGates, Refusal } from "./gates/core.ts";
import { OrchestrationStore } from "./store.ts";
import { Panes, spawnHelper, type LaunchConfig } from "./panes.ts";
import { socketPath } from "./transport.ts";
import { RequestRelay } from "./relay.ts";
import { writeReviewRequest } from "./relayFiles.ts";
import { reviewRequest, scoreRecords, QualityProtocolError } from "./gates/qualityProtocol.ts";
import { randomUUID } from "node:crypto";

export async function serve(
  root: string,
  config: LaunchConfig,
  createGates: (root: string, panes: Panes) => A2AGates = (root, panes) => new A2AGates(root, panes),
) {
  mkdirSync(root, { recursive: true, mode: 0o700 });
  root = realpathSync(root);
  const socket = socketPath(root);
  if (existsSync(socket)) throw new Error("socket exists; refusing to replace it");
  const helper = spawnHelper();
  const store = new OrchestrationStore(root);
  const panes = new Panes(root, store, config, (reason) => gates.setUserInputObserverStatus("failed", { reason }));
  const gates = createGates(root, panes);
  const relay = new RequestRelay(store);
  const daemon = randomUUID();
  gates.setUserInputObserverStatus("healthy");
  let stopping = false;
  let activeRequests = 0;
  let requestsDrained: (() => void) | undefined;
  const activityFinished = () => {
    activeRequests--;
    if (activeRequests === 0) { requestsDrained?.(); requestsDrained = undefined; }
  };
  const shutdown = async () => {
    stopping = true;
    // Requests and deferred receipt writes retain their stores until their
    // final results are durable. run observes beginShutdown at safe boundaries.
    if (activeRequests > 0) await new Promise<void>((resolve) => { requestsDrained = resolve; });
    await panes.shutdown();
    store.event("daemon_stopped", { pid: process.pid });
    await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    gates.close(); store.close();
    // Only this server's successfully bound endpoint and PID record are removed.
    if (existsSync(socket)) unlinkSync(socket);
    unlinkSync(join(root, "daemon.pid"));
  };
  const handle = async (envelope: any) => {
    const input = envelope.input;
    if (!input || typeof input.command !== "string") throw new Refusal("invalid_request");
    const identity = envelope.identity;
    if (identity) {
      panes.authenticate(identity);
      if (input.command !== "signal") throw new Refusal("worker_requests_require_stop");
    }
    if (input.command === "daemon_status") return { ok: true, pid: process.pid, node: process.version, root, helper };
    if (input.command === "scores_validate") {
      try {
        if (typeof input.file !== "string" || !isAbsolute(input.file) || !statSync(input.file).isFile()) throw new Refusal("invalid_path");
        const rows = scoreRecords(new TextDecoder("utf-8", { fatal: true }).decode(readFileSync(input.file)));
        return { ok: true, schema: 1, records: rows.length, imported: false };
      } catch (error) {
        if (error instanceof QualityProtocolError) return { ok: false, error: "invalid_scores", details: { field: error.field } };
        if ((error as NodeJS.ErrnoException).code === "ERR_ENCODING_INVALID_ENCODED_DATA") return { ok: false, error: "invalid_scores", details: { field: "encoding" } };
        if (["ENOENT", "EACCES", "EISDIR", "ENOTDIR", "ELOOP"].includes((error as NodeJS.ErrnoException).code ?? "")) return { ok: false, error: "local_io_failed", details: String(error) };
        throw error;
      }
    }
    if (input.command === "daemon_stop") {
      stopping = true;
      gates.beginShutdown();
      return { ok: true, pid: process.pid, stopping: true };
    }
    if (input.command === "orchestration_events") return { ok: true, events: store.read(input.task) };
    if (input.command === "pane_output") return { ok: true, ...panes.output(input.launch, input.offset, input.max_bytes) };
    if (input.command === "workbench_snapshot") {
      const result = await gates.call({ command: "status", task: input.task });
      if (!result.ok || !result.task) return result;
      const record = input.launch ? panes.launchRecord(input.launch) :
        result.task.current_attempt?.thread_id ? store.threadLaunch(result.task.current_attempt.thread_id) : undefined;
      if (record && record.task !== input.task) throw new Refusal("launch_task_mismatch");
      const pane = record ? panes.status(record.thread) : null;
      const launch = record ? { id: record.id, project: record.project, task: record.task, attempt: record.attempt,
        session: record.session, fence: record.fence, spec_rev: record.spec_rev, thread: record.thread,
        role: record.role, cli_version: record.cli_version, model_requested: record.model_requested,
        effort_requested: record.effort_requested, created_at: record.created_at } : null;
      return { ok: true, daemon, task: result.task, launch, pane, user_input_observer: result.user_input_observer };
    }
    if (input.command === "pane_status") return { ok: true, ...panes.status(input.thread) };
    if (input.command === "pane_process_info") return { ok: true, ...await panes.processInfo(input.thread) };
    if (input.command === "pane_release") return { ok: true, ...await panes.release(input.thread, input.reason) };
    if (input.command === "pane_dispatch") return { ok: true, dispatch: await panes.dispatch(panes.get(input.thread), input.body) };
    if (input.command === "signal") {
      if (!identity || identity.launch !== input.launch) throw new Refusal("signal_identity_required");
      let completedReview: { task: string; id: string } | undefined;
      await panes.signal(input.launch, input.raw_stdin, input.received_at, async (pane, stop, matched) => {
        let files = input.relay_files;
        if (pane.record.role === "reviewer") {
          if (!matched) return;
          let request: Record<string, any>;
          try { request = reviewRequest(stop.last_assistant_message); }
          catch (error) {
            if (!(error instanceof QualityProtocolError)) throw error;
            const caller = await panes.caller({ ...identity, native_session: stop.session_id });
            await gates.failReviewProtocol(pane.record.task, pane.record.review_id,
              { error: error.field, raw: stop.last_assistant_message, stop }, caller);
            pane.failed = "invalid_review_result";
            return;
          }
          files = [writeReviewRequest(pane.record.request_dir, request)];
        }
